use super::*;

/// Every tier's requirement is at least the one below it.
///
/// Stated as a FUNCTION so a caller can assert it on real data, not only in a test — the ladder
/// coming out of order would mean the tiers were built from figures that do not compose.
pub fn ladder_is_ordered(v: &ViableIncome) -> bool {
    v.tiers.windows(2).all(|w| w[1].worst_month.minor >= w[0].worst_month.minor)
}
